// Offline shell of a Kortex app (generated by `xtask build-app --web`; never edited per app).
// The build substitutes the exact inventory of public files, never user data. Navigation is
// network-first with the cached shell as fallback; listed files are served cache-first; engines
// (large, used on demand) are cached the first time they are fetched. The API origin is never
// intercepted: only same-origin GET requests are handled.
const CACHE = __CACHE__;
const PREFIX = __PREFIX__;
const RUNTIME = PREFIX + 'runtime';
const ASSETS = __ASSETS__;
const ON_DEMAND = __ON_DEMAND__;
const known = new Set(ASSETS.map(path => new URL(path, self.location).pathname));
self.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(ASSETS)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', event => {
  event.waitUntil(caches.keys().then(keys => Promise.all(
    keys.filter(key => key.startsWith(PREFIX) && key !== CACHE && key !== RUNTIME).map(key => caches.delete(key))
  )).then(() => self.clients.claim()));
});
self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (request.mode === 'navigate') {
    const shell = url.pathname.startsWith('/en/') || url.pathname === '/en' ? '/en/' : '/';
    event.respondWith(fetch(request).catch(async () => (await caches.open(CACHE)).match(shell)));
    return;
  }
  if (known.has(url.pathname)) {
    event.respondWith(caches.open(CACHE).then(async cache => (await cache.match(url.pathname)) || fetch(request)));
    return;
  }
  if (ON_DEMAND.some(prefix => url.pathname.startsWith(prefix))) {
    event.respondWith(caches.open(RUNTIME).then(async cache => {
      const hit = await cache.match(request);
      if (hit) return hit;
      const response = await fetch(request);
      if (response.ok) cache.put(request, response.clone());
      return response;
    }));
  }
});
